describe('Keyboard Navigation - Tab Key', () => {
  beforeEach(() => {
    cy.visit('/accessibility-demo');
  });

  it('should navigate all interactive elements using Tab key in correct order', () => {
    // Verify initial state
    cy.get('[data-testid="tab-button"]').should('be.visible');
    cy.get('[data-testid="dropdown-menu"]').should('be.visible');
    cy.get('[data-testid="form-input"]').should('be.visible');
    cy.get('[data-testid="checkbox"]').should('be.visible');
    cy.get('[data-testid="link-to-page"]').should('be.visible');
    cy.get('[data-testid="modal-trigger"]').should('be.visible');

    // Tab to first interactive element
    cy.get('[data-testid="tab-button"]').tab();
    cy.get('[data-testid="tab-button"]').should('have.focus');

    // Tab to second interactive element (dropdown)
    cy.get('[data-testid="dropdown-menu"]').tab();
    cy.get('[data-testid="dropdown-menu"]').should('have.focus');

    // Tab to third interactive element (form input)
    cy.get('[data-testid="form-input"]').tab();
    cy.get('[data-testid="form-input"]').should('have.focus');

    // Tab to fourth interactive element (checkbox)
    cy.get('[data-testid="checkbox"]').tab();
    cy.get('[data-testid="checkbox"]').should('have.focus');

    // Tab to fifth interactive element (link)
    cy.get('[data-testid="link-to-page"]').tab();
    cy.get('[data-testid="link-to-page"]').should('have.focus');

    // Tab to sixth interactive element (modal trigger)
    cy.get('[data-testid="modal-trigger"]').tab();
    cy.get('[data-testid="modal-trigger"]').should('have.focus');

    // Tab should wrap around to the first element
    cy.get('[data-testid="tab-button"]').tab();
    cy.get('[data-testid="tab-button"]').should('have.focus');
  });

  it('should handle focus management when modal opens and close', () => {
    // Tab to modal trigger
    cy.get('[data-testid="modal-trigger"]').tab();
    cy.get('[data-testid="modal-trigger"]').should('have.focus');

    // Open modal
    cy.get('[data-testid="modal-trigger"]').click();
    cy.get('[data-testid="modal-dialog"]').should('be.visible');

    // Focus should move inside the modal
    cy.get('[data-testid="modal-input"]').should('have.focus');

    // Tab inside modal
    cy.get('[data-testid="modal-input"]').tab();
    cy.get('[data-testid="modal-confirm-button"]').should('have.focus');

    // Tab should wrap inside modal
    cy.get('[data-testid="modal-confirm-button"]').tab();
    cy.get('[data-testid="modal-input"]').should('have.focus');

    // Close modal using Escape key
    cy.get('[data-testid="modal-dialog"]').type('{esc}');
    cy.get('[data-testid="modal-dialog"]').should('not.exist');

    // Focus should return to the element that triggered the modal
    cy.get('[data-testid="modal-trigger"]').should('have.focus');
  });
});
